def transform(grid):
    from collections import deque, Counter

    if not grid or not grid[0]:
        return grid

    # Most frequent color is background
    bg_counts = Counter()
    for row in grid:
        for cell in row:
            bg_counts[cell] += 1
    background = bg_counts.most_common(1)[0][0]

    n_rows, n_cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Sources: all 0s + edge 3s
    sources = set()
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] == 0:
                sources.add((r, c))
    for r in range(n_rows):
        if grid[r][0] == 3:
            sources.add((r, 0))
        if grid[r][n_cols-1] == 3:
            sources.add((r, n_cols-1))
    for c in range(n_cols):
        if grid[0][c] == 3:
            sources.add((0, c))
        if grid[n_rows-1][c] == 3:
            sources.add((n_rows-1, c))

    queue = deque(sources)
    visited = set(sources)

    dirs = [(0,1), (0,-1), (1,0), (-1,0)]
    while queue:
        r, c = queue.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n_rows and 0 <= nc < n_cols and (nr, nc) not in visited:
                visited.add((nr, nc))
                val = grid[nr][nc]
                if val == background:
                    result[nr][nc] = 3
                    queue.append((nr, nc))
                elif val == 7 or val == 3:
                    result[nr][nc] = 4
                    queue.append((nr, nc))
                elif val == 0:
                    result[nr][nc] = 0
                    queue.append((nr, nc))

    return result
